package com.hms.dao.impl;
import com.hms.config.DatabaseConnection; import com.hms.dao.PatientDao; import com.hms.model.Patient; import java.sql.*; import java.util.ArrayList; import java.util.List;
public class PatientDaoImpl implements PatientDao {
 private Patient map(ResultSet r)throws SQLException{return new Patient(r.getInt("patient_id"),r.getString("registration_no"),r.getString("full_name"),r.getString("gender"),r.getDate("date_of_birth").toLocalDate(),r.getString("phone"),r.getString("email"),r.getString("address"),r.getString("blood_group"),r.getString("emergency_contact"));}
 public List<Patient> findAll(String s)throws SQLException{List<Patient> out=new ArrayList<>();String q="SELECT * FROM patients WHERE registration_no LIKE ? OR full_name LIKE ? OR phone LIKE ? ORDER BY patient_id DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){String x="%"+(s==null?"":s)+"%";p.setString(1,x);p.setString(2,x);p.setString(3,x);try(ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}}return out;}
 public Patient save(Patient x)throws SQLException{return write(x,false);} public Patient update(Patient x)throws SQLException{return write(x,true);}
 private Patient write(Patient x,boolean update)throws SQLException{String q=update?"UPDATE patients SET registration_no=?,full_name=?,gender=?,date_of_birth=?,phone=?,email=?,address=?,blood_group=?,emergency_contact=? WHERE patient_id=?":"INSERT INTO patients(registration_no,full_name,gender,date_of_birth,phone,email,address,blood_group,emergency_contact) VALUES(?,?,?,?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){int i=1;p.setString(i++,x.registrationNo());p.setString(i++,x.fullName());p.setString(i++,x.gender());p.setDate(i++,Date.valueOf(x.dateOfBirth()));p.setString(i++,x.phone());p.setString(i++,x.email());p.setString(i++,x.address());p.setString(i++,x.bloodGroup());p.setString(i++,x.emergencyContact());if(update)p.setInt(i,x.patientId());p.executeUpdate();int id=x.patientId();if(!update)try(ResultSet k=p.getGeneratedKeys()){if(k.next())id=k.getInt(1);}return new Patient(id,x.registrationNo(),x.fullName(),x.gender(),x.dateOfBirth(),x.phone(),x.email(),x.address(),x.bloodGroup(),x.emergencyContact());}}
 public void delete(int id)throws SQLException{try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM patients WHERE patient_id=?")){p.setInt(1,id);p.executeUpdate();}}
}
